(()=>{'use strict';
const T=Tempo,$=id=>document.getElementById(id),names={up:'↑ 上移',down:'↓ 下移',left:'← 左移',right:'→ 右移',strike:'✦ 冲击',guard:'◇ 防守',wait:'· 等待'},targetNames={0:'1·青岚',1:'2·月汐'};
let state=T.fresh(),plan=T.defaultPlan(state),enemy=T.enemyPlan(state),selected=0,target=0,phase='plan',screen='intro',timer=null,deadline=0,pauseRemaining=0,effect=null,animation=null,totalChanges=0,poses=['idle','idle','idle','idle'];
const ctx=$('board').getContext('2d'),beatLength=()=> $('learning').checked?1800:1000;
const commandText=c=>{c=T.command(c);return `1 ${names[c.orders[0]]} / 2 ${names[c.orders[1]]}`;};
function notice(s){$('notice').textContent=s;}
function renderMaps(){$('maps').replaceChildren(...T.maps.map(m=>{const b=document.createElement('button');b.className='map-choice'+(m.id===state.mapId?' picked':'');b.innerHTML=`<strong>${m.name}</strong><small>${m.tag}</small>`;b.onclick=()=>reset(m.id);return b;}));$('map-name').textContent=T.mapOf(state).name;$('map-tip').textContent=T.mapOf(state).tip;}
function render(){
 $('learning').disabled=phase!=='plan';$('round').textContent=`第 ${Math.min(T.ROUNDS,state.round)} / ${T.ROUNDS} 轮`;$('pscore').textContent=state.score[0];$('escore').textContent=state.score[1];$('tokens').textContent=state.tokens?'● '.repeat(state.tokens):'已用完';
 $('phase-label').textContent=phase==='plan'?'01 / 规划':phase==='run'?'02 / 执行':'03 / 结算';$('phase-title').textContent=phase==='run'?'下一拍，指挥谁？':phase==='end'?'本局结束':'安排三拍协作';
 $('phase-help').textContent=phase==='run'?'点选一名角色，再选动作，花 1 点只改他的下一拍。':phase==='end'?'重新开始，再试另一种协作方式。':`点击表格的一格，再选动作。两人同拍执行各自的安排。每 ${beatLength()/1000} 秒执行一拍。`;
 $('timeline').replaceChildren(...plan.map((c,i)=>{const row=document.createElement('div');row.className='plan-row';const label=document.createElement('small');label.textContent=`第 ${i+1} 拍`;row.append(label);for(let j=0;j<2;j++){const b=document.createElement('button');b.className='unit-slot'+(phase==='plan'&&i===selected&&j===target?' selected':'')+(phase==='run'&&i===state.beat?' active':'')+(phase==='run'&&i<state.beat?' done':'');b.innerHTML=`<small>${targetNames[j]}</small>${names[c.orders[j]]}`;b.disabled=phase!=='plan'&&!(phase==='run'&&i===state.beat);b.onclick=()=>{if(phase==='plan')selected=i;target=j;render();draw();};row.append(b);}return row;}));

 $('intent').textContent=phase==='end'?'本局结束':commandText(enemy[phase==='run'?Math.min(state.beat,2):0],true);document.querySelector('.intent>span').textContent=phase==='run'?'对手下一拍':'对手首拍预告';
 const current=plan[phase==='run'?Math.min(2,state.beat):selected],action=current.orders[target];$('action-hint').textContent=`${targetNames[target]} ${names[action]}：${action==='strike'?'冲击直线上最近敌人，最多击退一格':action==='guard'?'消耗 1 点护盾格挡；护盾为 0 时无效':action==='wait'?'原地恢复护盾；据点无敌人贴身时才得分':'移动一格，撞墙或角色会停下'}。`;
 $('execute').disabled=phase!=='plan';$('execute').firstChild.textContent=phase==='run'?'执行中… ':phase==='end'?'本局已结束 ':'执行三拍计划 ';
 document.querySelectorAll('[data-action]').forEach(b=>b.disabled=!['plan','run'].includes(phase)||(phase==='run'&&state.tokens<=0));document.querySelectorAll('[data-target]').forEach(b=>{const v=Number(b.dataset.target);b.className=v===target?'picked':'';b.setAttribute?.('aria-pressed',String(v===target));b.disabled=!['plan','run'].includes(phase);});
 $('copy-order').disabled=phase!=='plan';$('strategy-tip').textContent=strategyTip();
 $('clock').textContent=phase==='plan'?'不限思考时间':phase==='end'?`${T.ROUNDS} 轮以内`:'下一拍即将结算';
}
function strategyTip(){const ours=state.units.slice(0,2),opponents=state.units.slice(2);for(let i=0;i<2;i++){const p=ours[i];if(T.zone(p,state)&&T.pressured(p,state)){const foe=opponents.find(q=>Math.abs(q.x-p.x)+Math.abs(q.y-p.y)===1),ally=ours[1-i];return `${p.name}被${foe.name}贴身压制，当前不能得分。${T.inRange(ally,foe,state)?`可试：${p.name}防守，${ally.name}冲击清敌。先看敌人的护盾和稳身。`:`让${ally.name}接近敌人，形成直线 2 格内的冲击位置，再配合解围。`}`;}}for(const p of ours)if(T.canScore(p,state))return `${p.name}已能占点得分。另一人可以支援，或贴近敌方占点角色，暂停其得分。`;return '先一起接近中央祭坛，让一人占点、另一人靠近支援。敌人贴身时，单靠防守不能拿分。';}
function chooseTarget(v){if(![0,1].includes(v)||!['plan','run'].includes(phase))return false;target=v;render();draw();return true;}
function choose(a){if(!Object.hasOwn(names,a)||!['plan','run'].includes(phase)||screen!=='match')return false;const index=phase==='run'?state.beat:selected,c=T.command(plan[index]);c.orders[target]=a;if(phase==='plan'){plan[index]=c;notice(`第 ${index+1} 拍：${commandText(c)}。两人会同时执行各自的动作。`);}else{if(!T.interrupt(state,plan,index,c)){notice(state.tokens<=0?'资源已用完，本轮按计划执行。':'该角色下一拍已经是这个动作，不需要花资源。');return false;}totalChanges++;notice(`只改${targetNames[target]}的下一拍，消耗 1 点；另一人的动作保留。`);}render();draw();return true;}
function copyOrder(){if(phase!=='plan')return;const c=T.command(plan[selected]);c.orders[1-target]=c.orders[target];plan[selected]=c;render();draw();}

function execute(){if(phase!=='plan'||screen!=='match')return false;phase='run';poses=poses.map(()=> 'idle');deadline=performance.now()+beatLength();notice('计划已锁定。查看对手预告，决定下一拍是否改招。');render();timer=setTimeout(tick,beatLength());return true;}
function tick(){if(phase!=='run'||screen!=='match')return;const before=state.units.map(p=>({...p}));effect=T.resolve(state,plan[state.beat],enemy[state.beat]);poses=effect.actions.map((a,i)=>T.actions[a]?'move':a==='strike'?'strike':a==='guard'&&effect.guardActive[i]?'guard':'idle');animation={from:before,start:performance.now()};
 $('beat-report').replaceChildren(...effect.events.map((events,i)=>{const p=document.createElement('p');p.className=i<2?'report-player':'report-enemy';p.textContent=`${i%2+1}·${state.units[i].name}：${events.join(' → ')}`;return p;}));notice(`第 ${state.beat} 拍：我方 +${effect.sideGain[0]} 分，对手 +${effect.sideGain[1]} 分。每人独立占点计分。`);
 if(T.winner(state)){end();return;}if(state.beat===3){phase='between';deadline=performance.now()+650;render();timer=setTimeout(nextRound,650);}else{deadline=performance.now()+beatLength();render();timer=setTimeout(tick,beatLength());}draw();
}
function nextRound(){const recovered=state.interrupts===0;T.finishRound(state);if(T.winner(state)){end();return;}phase='plan';poses=poses.map(()=> 'idle');plan=Array.from({length:3},()=>({orders:['wait','wait']}));enemy=T.enemyPlan(state);selected=0;target=0;notice(recovered?'本轮没有改招，恢复 1 点。下一轮可分头占点，也可协同行动。':'下一轮开始，改招资源没有恢复。');render();draw();}
function end(){phase='end';clearTimeout(timer);render();const w=T.winner(state);$('result-title').textContent=w==='draw'?'平局 · 协作相持':w==='player'?'你的队伍赢了':'对手抢占了先机';$('result-detail').textContent=`比分 ${state.score[0]} : ${state.score[1]} · 改招 ${totalChanges} 次。再试一次不同的双人路线。`;$('result').hidden=false;draw();}
function reset(mapId=state.mapId){clearTimeout(timer);state=T.fresh(mapId);poses=poses.map(()=> 'idle');plan=T.defaultPlan(state);enemy=T.enemyPlan(state);phase='plan';selected=0;target=0;effect=null;animation=null;totalChanges=0;pauseRemaining=0;$('result').hidden=true;notice('两人从相邻位置出发，默认填好进入中央祭坛的路线。点击表格中的青岚或月汐动作格，分别安排三拍。');$('beat-report').innerHTML='<strong>本拍怎么结算？</strong><p>执行后，分别显示四名角色的行动和得分。</p>';renderMaps();render();draw();}
function draw(){const time=performance.now(),age=animation?time-animation.start:0,visualPoses=poses.map(p=>p==='strike'&&age>650?'idle':p==='move'&&age>260?'idle':p);TempoRenderer.render(ctx,{state,plan,phase,selected,animation,effect,poses:visualPoses,time,selectedUnit:target});}
function enterMatch(){const wasIntro=screen==='intro';screen='match';document.body?.classList.toggle('match-active',true);$('intro-screen').hidden=true;$('match-screen').hidden=false;$('reset').hidden=false;$('show-match').className='quiet nav-active';$('show-rules').className='quiet';if(wasIntro&&['run','between'].includes(phase)){deadline=performance.now()+pauseRemaining;timer=setTimeout(phase==='run'?tick:nextRound,pauseRemaining);}render();draw();}
function showRules(){if(screen==='match'&&['run','between'].includes(phase)){pauseRemaining=Math.max(50,deadline-performance.now());clearTimeout(timer);}screen='intro';document.body?.classList.toggle('match-active',false);$('intro-screen').hidden=false;$('match-screen').hidden=true;$('reset').hidden=true;$('show-rules').className='quiet nav-active';$('show-match').className='quiet';$('enter-match').textContent='进入 / 返回对局 →';}
window.Match={enterMatch,showRules,get screen(){return screen;}};
let lastFrame=0;function loop(){if(screen==='match'){if(phase==='run')$('clock').textContent=`下一拍 ${Math.max(0,(deadline-performance.now())/1000).toFixed(1)}s`;if(performance.now()-lastFrame>32){draw();lastFrame=performance.now();}}requestAnimationFrame(loop);}
 $('learning').onchange=()=>{render();draw();};$('commands').onclick=e=>{const b=e.target.closest('[data-action]');if(b)choose(b.dataset.action);};$('unit-selector').onclick=e=>{const b=e.target.closest('[data-target]');if(b)chooseTarget(Number(b.dataset.target));};$('copy-order').onclick=copyOrder;$('execute').onclick=execute;$('reset').onclick=()=>reset();$('again').onclick=()=>reset();$('close-result').onclick=()=>{$('result').hidden=true;};$('show-rules').onclick=showRules;$('show-match').onclick=enterMatch;$('enter-match').onclick=enterMatch;
 document.addEventListener('keydown',e=>{if(screen!=='match'||e.repeat||e.ctrlKey||e.metaKey||e.altKey||/INPUT|TEXTAREA|SELECT/.test(e.target.tagName))return;if(['1','2','3'].includes(e.key)){e.preventDefault();e.key==='3'?copyOrder():chooseTarget(Number(e.key)-1);return;}const a={w:'up',s:'down',a:'left',d:'right',q:'strike',e:'guard',' ':'wait',ArrowUp:'up',ArrowDown:'down',ArrowLeft:'left',ArrowRight:'right'}[e.key]||{W:'up',S:'down',A:'left',D:'right',Q:'strike',E:'guard'}[e.key];if(a){e.preventDefault();choose(a);}else if(e.key==='Enter'&&e.target.tagName!=='BUTTON'){e.preventDefault();execute();}});
 if(document.modelContext?.registerTool){const life=new AbortController();const commandSchema={type:'object',properties:{orders:{type:'array',minItems:2,maxItems:2,items:{type:'string',enum:Object.keys(names)}}},required:['orders'],additionalProperties:false};for(const tool of [{name:'read_match_state',description:'读取界面、队伍位置、比分和三拍计划。',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({screen,phase,state,plan:plan.map(T.command)})},{name:'enter_match',description:'从规则演示进入或返回正式对局。',inputSchema:{type:'object',properties:{},additionalProperties:false},execute:()=>{enterMatch();return {screen};}},{name:'set_three_action_plan',description:'在对局规划阶段安排三个指令，每拍分别安排两人的动作。',inputSchema:{type:'object',properties:{actions:{type:'array',minItems:3,maxItems:3,items:commandSchema}},required:['actions'],additionalProperties:false},execute:input=>{if(screen!=='match'||phase!=='plan'||!Array.isArray(input.actions)||input.actions.length!==3)throw Error('请在对局规划阶段提供三个指令');const next=input.actions.map(T.command);plan=next;selected=0;target=0;render();draw();return {plan};}},{name:'execute_three_action_plan',description:'锁定并执行三拍协作计划。',inputSchema:{type:'object',properties:{},additionalProperties:false},execute:()=>{if(!execute())throw Error('请先进入对局规划界面');return {phase};}}]){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:life.signal})).catch(()=>{});}catch{}}window.addEventListener('pagehide',()=>life.abort(),{once:true});}
 renderMaps();render();showRules();requestAnimationFrame(loop);
})();
